    const playerRoute=/^\/[A-Za-z0-9_]{1,16}(?:\/(?:inventory|ender-chest|backpacks|bags|sacks|wardrobe|equipment|loadouts|slayer|dungeons|pets|mining|garden|bestiary|minions|collections|crimson|rift|misc|networth|notebook|accessories|essence|museum|mayor|events|ironpath))?\/?$/;
